71	async function collectHistory(rootPath: string): Promise<RepositoryHistory> {
72	  const output = await git(rootPath, [
73	    'log',
74	    `-n${HISTORY_COMMIT_LIMIT}`,
75	    '--name-only',
76	    '--no-renames',
77	    `--format=${COMMIT_MARK}%an${FIELD_MARK}%aI`,
78	  ]);
79	
80	  const files = new Map<string, FileHistory>();
81	  const pairCounts = new Map<string, number>();
82	
83	  for (const block of output.split(COMMIT_MARK)) {
84	    if (!block.trim()) {
85	      continue;
86	    }
87	    const newlineIndex = block.indexOf('\n');
88	    const header = newlineIndex === -1 ? block : block.slice(0, newlineIndex);
89	    const body = newlineIndex === -1 ? '' : block.slice(newlineIndex + 1);
90	    const [author, date] = header.split(FIELD_MARK);
91	    if (!author || !date) {
92	      continue;
93	    }
94	    const changed = body
95	      .split('\n')
96	      .map((entry) => entry.trim())
97	      .filter(Boolean);
98	
99	    for (const path of changed) {
100	      const existing = files.get(path);
101	      if (existing) {
102	        existing.commitCount += 1;
103	        existing.firstCommitAt = date;
104	      } else {
105	        // git log va de más reciente a más antiguo: el primer avistamiento es el último commit.
106	        files.set(path, {
107	          path,
108	          commitCount: 1,
109	          lastAuthor: author,
110	          lastCommitAt: date,
111	          firstCommitAt: date,
112	        });
113	      }
114	    }
115	
116	    if (changed.length >= 2 && changed.length <= CO_CHANGE_MAX_FILES_PER_COMMIT) {
117	      const sorted = [...changed].sort();
118	      for (let i = 0; i < sorted.length; i += 1) {
119	        for (let j = i + 1; j < sorted.length; j += 1) {
120	          const key = `${sorted[i]}\n${sorted[j]}`;
121	          pairCounts.set(key, (pairCounts.get(key) ?? 0) + 1);
122	        }
123	      }
124	    }
125	  }
126	
127	  const coChanges = [...pairCounts.entries()]
128	    .filter(([, count]) => count >= CO_CHANGE_MIN_COUNT)
129	    .sort((left, right) => right[1] - left[1])
130	    .slice(0, CO_CHANGE_TOP_PAIRS)
131	    .map(([key, count]) => {
132	      const [a = '', b = ''] = key.split('\n');
133	      return { a, b, count };
134	    });
135	
136	  return { files, coChanges };
137	}
