11	function buildDependencyIndex(store: KnowledgeStore, snapshotId: string, graph: CodeGraph, files: SourceFile[]) {
12	  const byPath = new Map(files.map((file) => [file.path, file]));
13	  const facts = new Map<string, { id: string; path: string; name: string; kind: string; contentHash: string; signature?: string | null }>();
14	  for (const file of files) { facts.set(file.id, { id: file.id, path: file.path, name: file.path, kind: 'file', contentHash: file.contentHash }); }
15	  for (const symbol of graph.symbols.values()) {
16	    facts.set(symbol.id, { id: symbol.id, path: symbol.path, name: symbol.qualifiedName, kind: symbol.kind,
17	      contentHash: symbol.contentHash, signature: symbol.signature });
18	  }
19	  for (const test of store.listTests(snapshotId)) {
20	    facts.set(test.id, { id: test.id, path: test.path, name: test.name, kind: 'test',
21	      contentHash: test.contentHash ?? byPath.get(test.path)?.contentHash ?? '' });
22	  }
23	  const mapped = new Set((store.db.prepare('SELECT DISTINCT target_id FROM symbol_references WHERE snapshot_id = ? AND is_definition = 1')
24	    .all(snapshotId) as { target_id: string }[]).map((row) => row.target_id));
25	  const outgoing = (id: string) => {
26	    const direct = (graph.outgoing.get(id) ?? []).filter((edge) => DEPENDENCY_EDGE_TYPES.has(edge.edgeType));
27	    const symbol = graph.symbols.get(id);
28	    const file = symbol && !mapped.has(id) ? byPath.get(symbol.path) : null;
29	    return [...direct, ...(file ? (graph.outgoing.get(file.id) ?? []).filter((edge) => edge.edgeType === 'IMPORTS') : [])];
30	  };
31	  const cache = new Map<string, ReturnType<typeof collect>>();
32	  function collect(subjectIds: string[], requestedDepth = 3) {
33	    const maxDepth = validateReanalysisDepth(requestedDepth);
34	    const seen = new Set(subjectIds);
35	    let frontier = [...seen];
36	    const dependencies: (NonNullable<ReturnType<typeof facts.get>> & { distance: number })[] = [];
37	    const topology: string[][] = [];
38	    const unresolved = new Set<string>();
39	    for (let depth = 1; depth <= maxDepth && frontier.length; depth += 1) {
40	      const next: string[] = [];
41	      for (const id of frontier) {
42	        for (const edge of outgoing(id)) {
43	          topology.push([id, edge.targetId, edge.edgeType, edge.analyzer]);
44	          if (seen.has(edge.targetId)) { continue; }
45	          seen.add(edge.targetId);
46	          const target = facts.get(edge.targetId);
47	          if (target) { dependencies.push({ ...target, distance: depth }); next.push(edge.targetId); }
48	          else { unresolved.add(edge.targetId); }
49	        }
50	      }
51	      frontier = next;
52	    }
53	    const boundary = new Set(frontier.flatMap((id) => outgoing(id).map((edge) => edge.targetId)).filter((id) => !seen.has(id)));
54	    dependencies.sort((a, b) => a.distance - b.distance || a.id.localeCompare(b.id));
55	    const fallback = subjectIds.some((id) => graph.symbols.has(id) && !mapped.has(id));
56	    return { maxDepth, resolution: fallback ? 'file-import-fallback' as const : 'indexed-dependencies' as const,
57	      fingerprint: contentHash(JSON.stringify({ maxDepth, dependencies, topology: topology.sort(), unresolved: [...unresolved].sort(), boundary: [...boundary].sort() })),
58	      dependencies, unresolvedTargets: unresolved.size, beyondDepth: boundary.size };
59	  }
60	  return {
61	    forSubjects(subjectIds: string[], maxDepth = 3) {
62	      const ids = [...new Set(subjectIds)].sort();
63	      const key = JSON.stringify([ids, maxDepth]);
64	      let result = cache.get(key);
65	      if (!result) { result = collect(ids, maxDepth); cache.set(key, result); }
66	      return result;
67	    },
68	  };
69	}
